module legacy_foreign_names;
pub struct ffi<T>{value:T;}
fn extern<T>(value:T)->T{return value;}
fn foreign(value:bytes)->(fn()->bytes){return fn()->bytes{return value;};}
server fn resource(value:file)->file{return value;}
server fn resource_callback()->(server fn(file)->file){return resource;}
fn main()->unit!{io}{
 let value:ffi<bytes> = ffi(foreign(utf8_bytes("Я\u0000🧠"))());
 print(encode_base64(extern(value.value)));print(extern(42));
}
test fn preserved_names()->unit{
 let value:ffi<bytes> = ffi(foreign(utf8_bytes("data"))());
 assert(extern(value.value)==utf8_bytes("data"));assert(extern(42)==42);
}
